using System.Text.Json;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using Microsoft.EntityFrameworkCore.Storage.ValueConversion;
using Microsoft.Extensions.DependencyInjection;
using PubSoft.Auditing;
using PubSoft.Domain;

namespace PubSoft.EntityFrameworkCore.Auditing;

/// <summary>Persisted audit row for one request/action plus its entity changes.</summary>
public sealed class AuditLogRecord : IMultiTenant
{
    /// <summary>Snowflake id assigned by the writing sink (IIdGenerator); never generated by the store.</summary>
    public long Id { get; set; }
    /// <summary>Tenant partition; null for host-scope.</summary>
    public long? TenantId { get; set; }
    /// <summary>Request/action start timestamp.</summary>
    public DateTimeOffset StartedAt { get; set; }
    /// <summary>HTTP method, when HTTP-sourced.</summary>
    public string? HttpMethod { get; set; }
    /// <summary>Request path.</summary>
    public string? RequestPath { get; set; }
    /// <summary>Client IP.</summary>
    public string? ClientIp { get; set; }
    /// <summary>User agent header.</summary>
    public string? UserAgent { get; set; }
    /// <summary>Acting subject id.</summary>
    public string? SubjectId { get; set; }
    /// <summary>Acting subject display name.</summary>
    public string? SubjectName { get; set; }
    /// <summary>Whether the actor held admin scope.</summary>
    public bool? IsAdministrator { get; set; }
    /// <summary>Whether the action succeeded.</summary>
    public bool Success { get; set; }
    /// <summary>Result status code.</summary>
    public int StatusCode { get; set; }
    /// <summary>Machine failure code on error.</summary>
    public string? FailureCode { get; set; }
    /// <summary>Elapsed milliseconds.</summary>
    public long DurationMilliseconds { get; set; }
    /// <summary>Audit category.</summary>
    public string? Category { get; set; }
    /// <summary>Logical action name.</summary>
    public string? Action { get; set; }
    /// <summary>Target entity type.</summary>
    public string? TargetType { get; set; }
    /// <summary>Target entity id.</summary>
    public string? TargetId { get; set; }
    /// <summary>Target display name.</summary>
    public string? TargetName { get; set; }
    /// <summary>Free-form detail payload.</summary>
    public string? Detail { get; set; }
    /// <summary>Child entity-change rows.</summary>
    public ICollection<AuditEntityChangeRecord> EntityChanges { get; } = new List<AuditEntityChangeRecord>();
}
